def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    for r in range(h-2):
      for c in range(w-2):
        if not all(grid[r+i][c+j] == (2 if (i,j)==(1,1) else 3) for i in range(3) for j in range(3)):
          continue
        # The long blue guide determines the perpendicular stroke.
        nh=sum(grid[r+1][x]==2 for x in range(w))
        nv=sum(grid[y][c+1]==2 for y in range(h))
        if nv >= nh:  # vertical guides: horizontal stroke through center
          for x in range(w):
            if grid[r+1][x]==0: out[r+1][x]=1
          for x in range(w):
            if grid[r+1][x]==2:
              for y in (r,r+2):
                if 0<=y<h and grid[y][x]==0: out[y][x]=1
        else:  # horizontal guides: vertical stroke through center
          for y in range(h):
            if grid[y][c+1]==0: out[y][c+1]=1
          for y in range(h):
            if grid[y][c+1]==2:
              for x in (c,c+2):
                if 0<=x<w and grid[y][x]==0: out[y][x]=1
    return out
