            for x in cols:
                for y in (r-1,r+1):
                    if 0<=y<h and grid[y][x]==0: out[y][x]=1
    else:
        for r,c in targets:
            for y in range(h):
                if grid[y][c]==0: out[y][c]=1
            for y in rows:
                for x in (c-1,c+1):
                    if 0<=x<w and grid[y][x]==0: out[y][x]=1
