    for r, c in targets:
        # Draw across the row containing the target center; retain guide-line 2s.
        for x in range(w):
            if grid[r][x] == 0:
                out[r][x] = 1
        # At each other guide crossing, add a 3-cell bar above and below;
        # these bars recolor guide 2s but leave the target's 3s intact.
        for x in guides:
            if x == c:
