def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    targets = []
    for r in range(h - 2):
        for c in range(w - 2):
            if all(grid[r+i][c+j] == (2 if (i, j) == (1, 1) else 3)
                   for i in range(3) for j in range(3)):
                targets.append((r+1, c+1))
    hguides = [r for r in range(h) if sum(v == 2 for v in grid[r]) > w // 2]
    vguides = [c for c in range(w) if sum(grid[r][c] == 2 for r in range(h)) > h // 2]
    if vguides:
        for r, c in targets:
            # Stroke perpendicular to the vertical guides.
            for x in range(w):
                if grid[r][x] == 0:
                    out[r][x] = 1
            # At each crossing, fill the surrounding 3x3 patch, preserving the red object.
            for x in vguides:
                for y in range(r-1, r+2):
                    for xx in range(x-1, x+2):
                        if 0 <= y < h and 0 <= xx < w and grid[y][xx] in (0, 2):
                            # Preserve the 2 on the stroke centerline.
                            if y == r and xx == x:
                                continue
                            out[y][xx] = 1
    elif hguides:
        for r, c in targets:
            # Stroke perpendicular to horizontal guides.
            for y in range(h):
                if grid[y][c] == 0:
                    out[y][c] = 1
            for y in hguides:
                for yy in range(y-1, y+2):
                    for x in range(c-1, c+2):
                        if 0 <= yy < h and 0 <= x < w and grid[yy][x] in (0, 2):
                            if yy == y and x == c:
                                continue
                            out[yy][x] = 1
    return out
